import os, glob

log_files = glob.glob("/home/USER/sentinel/**/*.log", recursive=True)
print(f"Found {len(log_files)} log files")
for lf in log_files[:20]:
    print(lf)

# Now search for ERROR lines
print("\nSearching for ERROR lines...")
for lf in log_files:
    try:
        with open(lf, 'r') as f:
            content = f.read()
            if 'ERROR' in content:
                lines = content.split('\n')
                for i, line in enumerate(lines):
                    if 'ERROR' in line:
                        print(f"{lf}:{i+1}: {line}")
    except:
        pass
